mapper.select:
SELECT 
  FROM act09_account_num
 WHERE act09_account_num_id = #{accountNumId}
   AND act09_company_id = #{companyId}

mapper.update:
UPDATE act09_account_num
   SET act09_num        = #{req.num},
       act09_start_date = #{req.startDate},
       act09_close_date = #{req.closeDate},
       act09_note       = #{req.note}
 WHERE act09_account_num_id = #{req.accountNumId}
   AND act09_company_id = #{companyId}

mapper.delete:
DELETE FROM act09_account_num
 WHERE act09_company_id = #{companyId}
   AND act09_account_num_id IN
#{accountNumId}
